-- GENERATED by `wfj generate` from data/spell/spell-0410.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("spell", {
  [410010] = { "Incidi sui tuoi gambali la runa Imposizione del Sacrificio:\n\n$I1\nFa sì che il membro del gruppo o dell'incursione bersaglio trasferisca all'incantatore il $N1% dei danni subiti. Dura $D1 o finché l'incantatore non ha trasferito il $N3% della sua salute massima.", nil, 0xdaa134e6, nil, "um" },
  [410011] = { "Incidi sui tuoi gambali la runa Inspiration Exemplar:\n\n$I1\nLa tua presenza ispiratrice dissolve periodicamente gli effetti di paura e di sonno sui membri del gruppo vicini.", nil, 0xe2484e74, nil, "um" },
  [410013] = { "Incidi sui tuoi bracciali la runa Martello del Virtuoso:\n\n$I1\nColpisce con il martello il bersaglio attuale e fino a $N1 bersagli aggiuntivi vicini, infliggendo a ciascuno danni da sacro pari a $N2 volte i danni al secondo della tua arma nella mano primaria. Tempo di recupero condiviso con Assalto del Crociato.", nil, 0x827a4325, nil, "um" },
  [410014] = { "Incidi sulla tua armatura per il torso la runa Tempesta Divina:\n\n$I1\nUn attacco istantaneo con l'arma che infligge il $N1% dei danni dell'arma a un massimo di $N2 nemici entro $N3 m. Tempesta Divina cura fino a $N4 membri del gruppo o dell'incursione per un totale pari al $N5% dei danni inflitti.", nil, 0xc83fa68f, nil, "um" },
  [410015] = { "Incidi sul tuo mantello la runa Luce Divina:\n\n$I1\nCura un bersaglio amico di $N1. Il $N2% di qualsiasi cura in eccesso sul bersaglio viene convertito in uno scudo assorbente che dura $D1. Più lanci di Luce Divina non accumulano questo scudo.\n\nLuce Divina beneficia di tutti i talenti e gli effetti che si attivano da Luce Sacra o la modificano.", nil, 0xf2c34b96, nil, "um" },
  [410021] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Assalti Selvaggi:\n\n$I1\nMentre sei in Forma Felina, Forma d'Orso o Dire Bear Form, i membri del gruppo o dell'incursione entro $N1 m ottengono una maggiore ferocia in combattimento. Ogni colpo in mischia ha una probabilità del $N2% di conferire all'attaccante un attacco aggiuntivo con il $N3% di potenza d'attacco in più. Nessun effetto se il bersaglio beneficia già di Totem della Furia del Vento.", nil, 0x279a79a2, nil, "um" },
  [410023] = { { "Incidi sui tuoi gambali la runa Ruggito Selvaggio:\n\n$I1\n|CFFFFFFFFRichiede Forma Felina|R\nMossa risolutiva che aumenta del $N1% i danni fisici inflitti mentre sei in Forma Felina. Dura di più per ogni punto combo:\n $N2 punto: $N3 s\n $N4 punti: $N5 s\n $N6 punti: $N7 s\n $N8 punti: $N9 s\n $N10 punti: $N11 s", "Incidi sui tuoi gambali la runa Ruggito Selvaggio:\n\n$I1\n|CFFFF2020Richiede Forma Felina|R\nMossa risolutiva che aumenta del $N1% i danni fisici inflitti mentre sei in Forma Felina. Dura di più per ogni punto combo:\n $N2 punto: $N3 s\n $N4 punti: $N5 s\n $N6 punti: $N7 s\n $N8 punti: $N9 s\n $N10 punti: $N11 s", shape = { "11/0", "11/0" }, key = { "13bea09af353746a", "47df89ae64f51870" } }, nil, 0x292d7b71, nil, "um" },
  [410025] = { "Incidi sui tuoi guanti la runa Dilaniamento:\n\n$I1\nMorde il bersaglio, infliggendo il $N1% dei danni normali più $N2 e generando un'elevata quantità di minaccia.", nil, 0x07e7bc10, nil, "um" },
  [410027] = { "Incidi sui tuoi stivali la runa Istinto di Sopravvivenza:\n\n$I1\nQuando viene attivato, ti conferisce il $N1% della tua salute massima e aumenta del $N2% tutte le cure non fisiche che effettui per $D1. Quando l'effetto termina, la salute viene persa. Utilizzabile in tutte le forme tranne Forma di Lunagufo.\n\nInoltre, rigeneri $N4 rabbia ogni volta che schivi mentre sei in Forma d'Orso o Dire Bear Form, $N5 energia mentre sei in Forma Felina, o il $N6% del tuo mana massimo mentre sei in qualsiasi altra forma.", nil, 0xb1a4b583, nil, "um" },
  [410028] = { "Incidi sui tuoi guanti la runa Crescita Rigogliosa:\n\n$I1\nCura il bersaglio e il suo gruppo di $N1 in $D1. I membri del gruppo devono trovarsi entro $N3 m dal bersaglio. La cura è rapida all'inizio e rallenta man mano che Crescita Rigogliosa si avvicina alla fine della sua durata.", nil, 0xf3ff628e, nil, "um" },
  [410029] = { "Incidi sulla tua cintura la runa Eclissi:\n\n$I1\nIl tuo incantesimo Ira Silvana riduce di $D1 il tempo di lancio dei tuoi prossimi $N1 incantesimi Fuoco Stellare. Conserva fino a $N3 cariche. Dura $D2.", nil, 0xf6c8a77f, nil, "um" },
  [410033] = { "Incidi sui tuoi gambali la runa Bocciolo di Vita:\n\nRiduce di $D1 il tempo di recupero globale delle tue abilità Rinvigorimento e Bocciolo di Vita e ottieni l'abilità Bocciolo di Vita:\n\n$I1\nCura il bersaglio di $N2 in $D2. Quando Bocciolo di Vita completa la sua durata o viene dissolto, il bersaglio viene curato istantaneamente di $N4 e il Druido recupera metà del costo dell'incantesimo. Questo effetto può accumularsi fino a $N5 volte sullo stesso bersaglio.", nil, 0xcebd1350, nil, "um" },
  [410059] = { "Incidi sulla tua cintura la runa Nutrizione:\n\n$I1\nCura un bersaglio amico di $N1. Cura un ulteriore $N2% se sul bersaglio è attivo un tuo effetto di Rinvigorimento, Ricrescita, Bocciolo di Vita o Crescita Rigogliosa. Questo incantesimo beneficia di tutti gli effetti associati a Tocco Curativo o Ricrescita e li attiva.", nil, 0x4c436437, nil, "um" },
  [410060] = { "Incidi sui tuoi stivali la runa Stato Onirico:\n\n$I1\nI critici non periodici dei tuoi incantesimi offensivi ti conferiscono il $N1% della tua rigenerazione del mana durante il lancio per $D1.", nil, 0xddd238a5, nil, "um" },
  [410061] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Fury of Stormrage:\n\n$I1\nRiduce del $N1% il costo in mana di Ira Silvana e, ogni volta che infliggi danni con Ira Silvana, hai una probabilità del $N2% che il tuo prossimo lancio di Tocco Curativo entro $D1 sia istantaneo e lanciabile in qualsiasi forma. Permette di lanciare Ira Silvana in forma di Albero della Vita.", nil, 0xec987f0e, nil, "um" },
  [410093] = { "Incidi sulla tua cintura la runa ⟦Fire Nova=Esplosione di Fuoco⟧:\n\n$I1\nIl tuo incantesimo Totem dell'⟦Fire Nova=Esplosione di Fuoco⟧ è sostituito da ⟦Fire Nova=Esplosione di Fuoco⟧, che fa emettere danni al tuo totem del fuoco attuale nella sua posizione.", nil, 0x579f11e5, nil, "um" },
  [410094] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Sovraccarico:\n\n$I1\nConferisce ai tuoi incantesimi Dardo Fulminante e Catena di Fulmini una probabilità del $N1% di lanciare sullo stesso bersaglio, senza costi aggiuntivi, un secondo incantesimo simile che infligge metà dei danni e non genera minaccia.", nil, 0xaaca0719, nil, "um" },
  [410095] = { "Incidi sui tuoi guanti la runa ⟦Lava Burst=Getto di Lava⟧:\n\n$I1\nScagli lava fusa contro il bersaglio, infliggendo $N1 danni da fuoco. Se la tua Folgore del Fuoco è sul bersaglio, ⟦Lava Burst=Getto di Lava⟧ infligge il $N2% di danni in più.", nil, 0x5526c59e, nil, "um" },
  [410096] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Specializzazione: ⟦Dual Wield=Combattimento con Due Armi⟧:\n\n$I1\nAumenta del $N1% la tua probabilità di colpire sia con gli incantesimi sia con gli attacchi in mischia mentre combatti con due armi, la tua abilità Assalto della Tempesta ora colpisce con entrambe le armi mentre combatti con due armi, e aumenta del $N2% i danni inflitti dall'arma nella mano secondaria.", nil, 0x74d5756d, nil, "um" },
  [410097] = { "Incidi sui tuoi guanti la runa Scudo d'Acqua:\n\n$I1\nL'incantatore è circondato da $N1 globi d'acqua. Quando un incantesimo, un attacco in mischia o a distanza colpisce l'incantatore, o quando uno degli incantesimi dell'incantatore ottiene un effetto critico, all'incantatore viene rigenerato il $N2% del mana massimo, consumando un globo d'acqua. Si può attivare un solo globo ogni pochi secondi. Dura $D1.\n\nSullo Sciamano può essere attivo un solo Scudo Elementale alla volta.", nil, 0xba523d1e, nil, "um" },
  [410098] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Maestria nello Scudo:\n\n$I1\nOgni volta che blocchi, rigeneri mana pari al $N1% del tuo mana massimo e ottieni Armatura pari al $N2% del valore di armatura del tuo scudo, effetto che si accumula fino a $N3 volte. Inoltre ottieni sempre il $N4% di probabilità di blocco in più e il $N5% di valore di blocco in più.\n\nInoltre, ogni volta che usi un'abilità Folgore, ottieni $N6 danni magici per ogni punto di abilità in Difesa oltre $N7. Dura $D1.", nil, 0xfc4a3b79, nil, "um" },
  [410099] = { "Incidi sui tuoi gambali la runa Guida Ancestrale:\n\n$I1\nPer i prossimi $D1, il $N2% dei tuoi danni viene convertito in cure su un massimo di $N3 membri del gruppo vicini, e il $N4% delle tue cure viene convertito in danni sul bersaglio più recente della tua Folgore del Fuoco.", nil, 0x00771271, nil, "um" },
  [410100] = { "Incidi sulla tua cintura la runa Arma del Maelstrom:\n\n$I1\nQuando infliggi danni con un attacco in mischia, hai una probabilità di ridurre del $N1% il tempo di lancio e il costo in mana del tuo prossimo incantesimo Dardo Fulminante. Si accumula fino a $N2 volte. Dura $D1.", nil, 0x127a4c8a, nil, "um" },
  [410101] = { "Incidi sui tuoi gambali la runa ⟦Earth Shield=Scudo di Terra⟧:\n\n$I1\nProtegge il bersaglio con uno scudo di terra, riducendo del $N1% il tempo di lancio o di canalizzazione perso quando subisce danni e facendo sì che gli attacchi curino il bersaglio protetto di $N2. Questo effetto può verificarsi solo una volta ogni pochi secondi. $N3 cariche. Dura $D1. ⟦Earth Shield=Scudo di Terra⟧ può essere posto su un solo bersaglio alla volta.", nil, 0x639cc53d, nil, "um" },
  [410103] = { "Incidi sui tuoi stivali la runa Spirit of the Alpha:\n\n$I1\nInfonde nel bersaglio lo spirito di un lupo alfa, aumentando del $N1% tutta la minaccia generata dal bersaglio per $D1. Limite: $N3 bersaglio. Se lanciato su un bersaglio diverso da te, lo Sciamano ottiene anche Loyal Beta, che aumenta del $N4% i danni fisici inflitti e riduce del $N5% tutta la minaccia generata per $D2. Un bersaglio non può avere contemporaneamente Spirit of the Alpha e Loyal Beta.", nil, 0x1e19e35c, nil, "um" },
  [410104] = { "Incidi sui tuoi guanti la runa Sferzata Lavica:\n\n$I1\nCarichi di lava l'arma nella mano secondaria, infliggendo istantaneamente il $N1% dei danni dell'arma nella mano secondaria. I danni aumentano del $N2% se l'arma nella mano secondaria è incantata con Arma della Lingua di Fuoco.", nil, 0x98cf6597, nil, "um" },
  [410105] = { "Incidi sui tuoi bracciali la runa Marea Benefica:\n\n$I1\nCura un bersaglio amico di $N1 in $D1 e aumenta del $N3% l'efficacia dei tuoi lanci di Catena di Guarigione diretti su quel bersaglio.", nil, 0xa6711e36, nil, "um" },
  [410107] = { "Incidi sui tuoi gambali la runa Way of Earth:\n\n$I1\nMentre Arma della Roccia Dura è attiva sulla tua arma nella mano primaria e hai uno scudo equipaggiato, generi il $N1% di minaccia in più, ottieni il $N2% di salute in più, subisci il $N3% di danni in meno, la tua probabilità di subire colpi critici dagli attacchi in mischia è ridotta del $N4%, e Folgore della Terra provoca i bersagli inducendoli ad attaccarti e ha un tempo di recupero separato dagli altri incantesimi Folgore, ma la sua portata è ridotta alla distanza da mischia. Tuttavia, la portata dei tuoi incantesimi Dardo Fulminante, Catena di Fulmini, Catena di Guarigione, Ondata di Cura e Getto di Lava è ridotta di $N5 m.", nil, 0xc958e370, nil, "um" },
  [410109] = { "Incidi sulla tua cintura la runa Tiro Stabilizzato:\n\n$I1\nUn tiro stabilizzato che infligge il $N1% dei danni dell'arma a distanza.", nil, 0x78ab7381, nil, "um" },
  [410110] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Affinità Animale:\n\n$I1\nI danni e la salute del tuo famiglio aumentano del $N1% e la sua rigenerazione di Focus del $N2%. Inoltre, il Ringhio del tuo famiglio ora provoca anche il bersaglio, inducendolo ad attaccarlo per $D1.", nil, 0xb471819e, nil, "um" },
  [410111] = { "Incidi sui tuoi gambali la runa Tiro Mortale:\n\n$I1\nTenti di finire un bersaglio ferito con un attacco a distanza che infligge il $N1% dei danni dell'arma più $N2. Tiro Mortale non ha una portata minima. Il tempo di recupero di Tiro Mortale si azzera se viene usato su un nemico con il $N3% di salute o meno.", nil, 0x54750420, nil, "um" },
  [410113] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Precisione da Cecchino:\n\n$I1\nAumenta del $N1% la tua probabilità di colpo critico e riduce del $N2% il costo in mana di tutte le tue abilità di tiro.", nil, 0x05d24437, nil, "um" },
  [410114] = { "Incidi sulla tua cintura la runa ⟦Expose Weakness=Debolezza Esposta⟧:\n\n$I1\nI tuoi critici in mischia e a distanza aumentano la tua potenza d'attacco del $N1% della tua Agilità attuale per $D1.", nil, 0x79930c44, nil, "um" },
  [410115] = { "Incidi sui tuoi guanti la runa Cobra Slayer:\n\n$I1\nMorso della Mangusta ora ha una probabilità del $N1% di attivarsi a ogni tuo attacco in mischia, e del $N2% quando un nemico schiva. Questa probabilità si accumula, aumentando del $N3% a ogni attacco successivo se non si azzera. Morso della Mangusta infligge anche danni aggiuntivi pari al $N4% della tua potenza d'attacco.", nil, 0xff8b8fc8, nil, "um" },
  [410116] = { "Incidi sui tuoi stivali la runa Specializzazione: ⟦Dual Wield=Combattimento con Due Armi⟧:\n\n$I1\nAumenta del $N1% i danni inflitti dall'arma nella mano secondaria e fa sì che il tuo Assalto del Raptor colpisca con entrambe le armi quando combatti con due armi.", nil, 0x977a0a79, nil, "um" },
  [410121] = { "Incidi sui tuoi guanti la runa Tiro della Chimera:\n\n$I1\nInfliggi il $N1% dei danni dell'arma, rinnovando il Morso attivo sul tuo bersaglio e attivando un effetto:\n\nMorso del Serpente - Infligge istantaneamente il $N2% dei danni inflitti dal tuo Morso del Serpente.\n\nMorso della Vipera - Ti rigenera istantaneamente mana pari al $N3% della quantità totale prosciugata dal tuo Morso della Vipera.\n\nMorso dello Scorpide - Tenta di disarmare il bersaglio per $D1. Questo effetto non può verificarsi più di una volta ogni $N5 min.", nil, 0x58d16ab2, nil, "um" },
  [410122] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Lupo Solitario:\n\n$I1\nInfliggi il $N1% di danni in più con tutti gli attacchi mentre non hai un famiglio attivo.", nil, 0x1ee57669, nil, "um" },
  [410140] = { nil, "Inabilitato dal veleno di un ragno delle caverne", nil, 0x49beb142, "mu" },
  [410144] = { nil, "Assorbe danni fisici pari al $N1% della tua potenza d'attacco per $N2 colpi.", nil, 0xbbc73bf1, "mu" },
  [410156] = { "Ti conferisce un attacco aggiuntivo. Inoltre, le prossime $N1 fonti di danni da natura inflitte al bersaglio sono aumentate del $N2%. Dura $D1.", nil, 0xcf85f05a, nil, "um" },
  [410163] = { nil, "Le sue ferite sono gravemente infette", nil, 0xfaf5d9be, "mu" },
  [410176] = { "Carica un bersaglio entro $N1 m e lo colpisce al cranio, interrompendone il lancio d'incantesimi e impedendo di lanciare incantesimi di quella scuola per $D1. Condivide il tempo di recupero con Carica Ferina.", nil, 0xf9555e00, nil, "um" },
  [410412] = { "Costringe il bersaglio ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.", nil, 0x71de38fd, nil, "um" },
  [410881] = { nil, "La Luce pervade questo luogo e calma i tuoi pensieri.", nil, 0x201a790e, "mu" },
  [410935] = { nil, "La meditazione ha espanso la tua mente, dandoti la lucidità per apprendere nuovi incantesimi dalle Memorie sparse per il mondo.", nil, 0x0f1e11e9, "mu" },
  [410958] = { "Concentrati sulla Memoria per apprendere un nuovo incantesimo. Richiede una mente schiarita dalla meditazione sui misteri spirituali di Azeroth.", nil, 0x71e0620a, nil, "um" },
  [410970] = { nil, "Le ombre del Vuoto ti conferiscono una cupa precognizione, permettendoti di apprendere nuovi incantesimi dalle Profezie sparse per il mondo.", nil, 0x78f5bc21, "mu" },
  [410971] = { "Concentrati sulla Profezia per apprendere un nuovo incantesimo. Richiede una mente concentrata dalla meditazione su due misteri spirituali di Azeroth.", nil, 0xe0dfb45b, nil, "um" },
})
